CREATE TABLE public.admin_feature_permissions (user_id uuid NOT NULL, feature text NOT NULL CHECK (feature IN ('overview','users','restrictions','withdrawals','payouts','kyc','support','audit','plans','prices','tasks','campaigns','proof_reviews')), PRIMARY KEY(user_id,feature));
GRANT SELECT ON public.admin_feature_permissions TO authenticated;
GRANT ALL ON public.admin_feature_permissions TO service_role;
ALTER TABLE public.admin_feature_permissions ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.is_admin(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.admin_roles WHERE user_id=_uid AND role='admin') $$;
CREATE POLICY "Read own permissions or full admin" ON public.admin_feature_permissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin(auth.uid()));
CREATE OR REPLACE FUNCTION public.has_admin_feature(_uid uuid,_feature text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin(_uid) OR EXISTS(SELECT 1 FROM public.admin_roles r JOIN public.admin_feature_permissions p ON p.user_id=r.user_id WHERE r.user_id=_uid AND r.role='subadmin' AND p.feature=_feature) $$;
CREATE OR REPLACE FUNCTION public.require_admin_feature(_feature text) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_admin_feature(auth.uid(),_feature) THEN RAISE EXCEPTION 'Feature access denied: %',_feature USING ERRCODE='42501'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.admin_my_access() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('role',COALESCE((SELECT role FROM public.admin_roles WHERE user_id=auth.uid()),''),'features',COALESCE((SELECT jsonb_agg(feature ORDER BY feature) FROM public.admin_feature_permissions WHERE user_id=auth.uid()),'[]'::jsonb)) $$;
CREATE OR REPLACE FUNCTION public.admin_list_subadmins() RETURNS TABLE(user_id uuid,email text,features text[]) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.admin_guard(); RETURN QUERY SELECT r.user_id,u.email::text,ARRAY(SELECT p.feature FROM public.admin_feature_permissions p WHERE p.user_id=r.user_id ORDER BY p.feature) FROM public.admin_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.role='subadmin'; END $$;
CREATE OR REPLACE FUNCTION public.admin_set_subadmin_features(p_user_id uuid,p_features text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.admin_guard(); IF p_features IS NULL OR EXISTS(SELECT 1 FROM unnest(p_features) f WHERE f IS NULL OR f NOT IN ('overview','users','restrictions','withdrawals','payouts','kyc','support','audit','plans','prices','tasks','campaigns','proof_reviews')) THEN RAISE EXCEPTION 'Invalid features'; END IF; PERFORM 1 FROM public.admin_roles WHERE user_id=p_user_id AND role='subadmin' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Subadmin account required'; END IF; DELETE FROM public.admin_feature_permissions WHERE user_id=p_user_id; INSERT INTO public.admin_feature_permissions(user_id,feature) SELECT p_user_id,f FROM (SELECT DISTINCT unnest(p_features) f) q; INSERT INTO public.audit_log(actor_id,action,target_user_id,target_reference) VALUES(auth.uid(),'subadmin_features_updated',p_user_id,array_to_string(p_features,',')); END $$;
REVOKE ALL ON FUNCTION public.has_admin_feature(uuid,text),public.require_admin_feature(text),public.admin_my_access(),public.admin_list_subadmins(),public.admin_set_subadmin_features(uuid,text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_admin_feature(uuid,text),public.require_admin_feature(text),public.admin_my_access(),public.admin_list_subadmins(),public.admin_set_subadmin_features(uuid,text[]) TO authenticated,service_role;
DO $$ DECLARE x record; def text; BEGIN FOR x IN SELECT * FROM (VALUES ('admin_overview','overview'),('admin_list_users','users'),('admin_list_withdrawals','withdrawals'),('admin_list_kyc','kyc'),('admin_list_audit','audit'),('admin_list_support','support'),('admin_set_user_restriction','restrictions'),('admin_review_withdrawal','withdrawals'),('admin_mark_withdrawal_paid','payouts'),('admin_review_kyc','kyc'),('admin_set_setting','prices'),('admin_set_fx','prices'),('admin_move_plan','plans'),('admin_list_cn_submissions','proof_reviews'),('admin_review_cn_submission','proof_reviews'),('admin_pay_cn_campaign','campaigns')) m(fn,feature) LOOP SELECT pg_get_functiondef(p.oid) INTO STRICT def FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=x.fn; IF def !~* 'perform (public\.)?admin_guard\(\);' THEN RAISE EXCEPTION 'Missing guard in %',x.fn; END IF; def:=regexp_replace(def,'perform (public\.)?admin_guard\(\);',format('perform public.require_admin_feature(%L);',x.feature),'i'); IF x.fn='admin_list_withdrawals' THEN def:=replace(def,'perform public.require_admin_feature(''withdrawals'');','IF NOT (public.has_admin_feature(auth.uid(),''withdrawals'') OR public.has_admin_feature(auth.uid(),''payouts'')) THEN RAISE EXCEPTION ''Feature access denied'' USING ERRCODE=''42501''; END IF;'); END IF; IF x.fn='admin_list_users' THEN def:=replace(def,'perform public.require_admin_feature(''users'');','IF NOT (public.has_admin_feature(auth.uid(),''users'') OR public.has_admin_feature(auth.uid(),''restrictions'')) THEN RAISE EXCEPTION ''Feature access denied'' USING ERRCODE=''42501''; END IF;'); END IF; IF x.fn='admin_review_cn_submission' THEN def:=replace(def,'perform public.require_admin_feature(''proof_reviews'');','perform public.require_admin_feature(''proof_reviews''); IF EXISTS(SELECT 1 FROM public.cn_submissions WHERE id=p_id AND campaign_id IS NOT NULL) THEN perform public.require_admin_feature(''campaigns''); END IF;'); END IF; IF x.fn='admin_list_cn_submissions' THEN def:=replace(def,'ORDER BY (s.status','WHERE (s.campaign_id IS NULL OR public.has_admin_feature(auth.uid(),''campaigns'')) ORDER BY (s.status'); END IF; EXECUTE def; END LOOP; END $$;
DO $$ DECLARE x record; expr text; BEGIN FOR x IN SELECT p.polname,c.relname,p.polcmd,pg_get_expr(p.polqual,p.polrelid) qual,pg_get_expr(p.polwithcheck,p.polrelid) chk FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('investment_plans','cn_tasks','cn_campaigns') LOOP expr:=CASE x.relname WHEN 'investment_plans' THEN 'plans' WHEN 'cn_tasks' THEN 'tasks' ELSE 'campaigns' END; IF x.qual LIKE '%is_admin%' OR x.chk LIKE '%is_admin%' THEN EXECUTE format('ALTER POLICY %I ON public.%I %s %s',x.polname,x.relname,CASE WHEN x.qual IS NOT NULL THEN 'USING ('||replace(x.qual,'is_admin(auth.uid())',format('has_admin_feature(auth.uid(), %L)',expr))||')' ELSE '' END,CASE WHEN x.chk IS NOT NULL THEN 'WITH CHECK ('||replace(x.chk,'is_admin(auth.uid())',format('has_admin_feature(auth.uid(), %L)',expr))||')' ELSE '' END); END IF; END LOOP; END $$;